<?php require_once '_bootstrap.php';require_admin();$db=admin_db();if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$id=(int)$_POST['id'];$status=$_POST['status']==='resolved'?'resolved':'open';$response=trim($_POST['admin_response']??'');$resolved=$status==='resolved'?'NOW()':'NULL';$s=$db->prepare("UPDATE message SET status=?,admin_response=?,resolved_at=$resolved WHERE id=?");$s->bind_param('ssi',$status,$response,$id);$s->execute();admin_audit($db,'respond','message',(string)$id,$status);redirect_with_message('messages.php','Message updated.');}$messages=$db->query('SELECT * FROM message ORDER BY created_at DESC,id DESC');$pageTitle='Messages';include '_header.php';?><div class="page-head"><div><span>Customer support</span><h1>Messages</h1></div></div><section class="message-grid"><?php while($m=$messages->fetch_assoc()):?><article class="message-card"><div class="message-meta"><span class="pill"><?php echo e($m['status']);?></span><time><?php echo e($m['created_at']);?></time></div><h2><?php echo e($m['sub']);?></h2><p class="sender"><?php echo e($m['fname'].' '.$m['lname']);?> &lt;<?php echo e($m['email']);?>&gt;</p><p><?php echo nl2br(e($m['message']));?></p><form method="post"><?php echo csrf_input();?><input type="hidden" name="id" value="<?php echo (int)$m['id'];?>"><textarea name="admin_response" placeholder="Internal response or resolution note"><?php echo e($m['admin_response']);?></textarea><div><select name="status"><option value="open" <?php echo $m['status']==='open'?'selected':'';?>>Open</option><option value="resolved" <?php echo $m['status']==='resolved'?'selected':'';?>>Resolved</option></select><button>Save response</button></div></form></article><?php endwhile;?></section><?php include '_footer.php';?>
